        assert_eq!(zone_slot_for_offset(SPAN_END, BS), ZoneSlot::OutOfRange);
    }

    #[test]
    fn a_zero_block_size_is_out_of_range_not_a_division_by_zero() {
        assert_eq!(zone_slot_for_offset(0, 0), ZoneSlot::OutOfRange);
