        m.m_type
    } else {
        OK
    };
    if rc == ENOSYS {
        denied += 1;
    } else {
        diag_fmt(format_args!("fs.deny FAIL unknown rc={rc}"));
    }

    if denied == FS_DENIAL_PROBES {
        diag_fmt(format_args!("fs.deny ok n={denied}"));
    }
    for gid in [good, not_mine, read_only] {
        let _ = grants.revoke(gid);
    }
