/// caller advancing by it terminates in at most `size.div_ceil(bs)` rounds.
pub fn next_dir_chunk(off: usize, size: usize, bs: usize) -> Option<usize> {
    if off >= size || bs == 0 {
        return None;
    }
    Some((size - off).min(bs))
